//! A data directory written before records were versioned (Task 3.1 step 4).
//!
//! `tests/fixtures/pre_versioning_records/` was generated by
//! `write_pre_versioning_fixture` while every record encoder still wrote raw
//! postcard. It holds one durable event per record type, plus the snapshot the
//! engine wrote on close. `expected.txt` lists every projection entry as it
//! decoded then.
//!
//! Do not regenerate the fixture: the generator now writes versioned records,
//! so a regenerated directory would no longer prove anything about old data.

use super::golden_records as sample;
use crate::crypto::bootstrap::BootstrapSource;
use crate::engine::WabiDbConfig;
use crate::engine::locks::ProjectionState;
use crate::engine::WabiDbEngine;
use crate::format::record::RecordKind;
use crate::projections::codec::RecordCodec;
use crate::projections::{
    album_items, albums, channel_members, dm_identities, dm_message_recipients, dm_messages,
    emotes, forum, gallery, incidents, layouts, lore, messages, payments, reactions, users,
    webhooks, whiteboard_docs, wiki,
};
use crate::sequencer::types::{CommandCommit, EventToWrite};
use std::path::{Path, PathBuf};

const BOOTSTRAP: [u8; 32] = [0x31; 32];

fn fixture_dir() -> PathBuf {
    Path::new(env!("CARGO_MANIFEST_DIR")).join("tests/fixtures/pre_versioning_records")
}

fn config(path: &Path) -> WabiDbConfig {
    let mut config = WabiDbConfig::new(path.to_path_buf(), BootstrapSource::Provided(BOOTSTRAP));
    config.allow_init = true;
    config
}

/// Decoded form of one projection value, by index. Indexes not listed hold
/// keys, ids or counters rather than record bytes and are compared raw.
fn describe_value(index: &str, value: &[u8]) -> String {
    fn show<T: std::fmt::Debug>(decoded: crate::error::Result<T>) -> String {
        match decoded {
            Ok(value) => format!("{value:?}"),
            Err(error) => format!("DECODE ERROR: {error}"),
        }
    }
    match index {
        "users" => show(users::decode_record(value)),
        "channel_members" => show(channel_members::decode_record(value)),
        // The three secondary indexes store the message event payload itself.
        "messages" | "messages_by_channel" | "messages_by_author" | "messages_by_channel_time" => {
            show(messages::decode_record(value))
        }
        "reactions" => show(reactions::decode_reaction(value)),
        "emotes" => show(emotes::decode_record(value)),
        "webhooks" => show(webhooks::decode_record(value)),
        "user_layouts" => show(layouts::decode_record(value)),
        "whiteboard_docs" => show(whiteboard_docs::decode_record(value)),
        "albums" => show(albums::decode_record(value)),
        "album_items" => show(album_items::decode_record(value)),
        "wiki_pages" => show(wiki::decode_record(value)),
        "wiki_revisions" => show(wiki::decode_revision_record(value)),
        "forum_posts" => show(forum::decode_record(value)),
        "incidents" => show(incidents::decode_record(value)),
        "gallery_works" => show(gallery::decode_record(value)),
        "gallery_feedback" => show(gallery::decode_feedback_record(value)),
        "lore_repos" => show(lore::decode_repo_record(value)),
        "lore_commits" => show(lore::decode_record(value)),
        "lore_file_changes" => show(lore::decode_change_record(value)),
        "lore_tokens" => show(lore::decode_token_record(value)),
        "lore_bindings" => show(lore::decode_binding_record(value)),
        "lore_promotes" => show(lore::decode_promote_record(value)),
        "payment_account_links" => show(payments::PaymentAccountLinkRecord::decode(value)),
        "payment_intents" => show(payments::PaymentIntentRecord::decode(value)),
        "payment_policies" => show(payments::PaymentPolicyRecord::decode(value)),
        "payment_user_blocks" => show(payments::PaymentUserBlockRecord::decode(value)),
        "dm_messages" => show(dm_messages::decode_record(value)),
        "dm_message_recipients" => show(dm_message_recipients::decode_record(value)),
        "dm_identities" => show(dm_identities::decode_record(value)),
        _ => format!("raw {}", hex::encode(value)),
    }
}

/// Every projection entry, one line each, sorted: `index key description`.
/// Reads the state through a snapshot written to a scratch directory, since
/// that is the only public way to enumerate every index.
fn describe_state(state: &ProjectionState) -> String {
    let scratch = tempfile::tempdir().unwrap();
    std::fs::create_dir_all(scratch.path().join("projections")).unwrap();
    state.save_snapshot(scratch.path()).unwrap();
    let json: serde_json::Value = serde_json::from_slice(
        &std::fs::read(ProjectionState::snapshot_path(scratch.path())).unwrap(),
    )
    .unwrap();
    let mut lines = Vec::new();
    for index in json["indexes"].as_array().unwrap() {
        let name = index[0].as_str().unwrap();
        for entry in index[1].as_array().unwrap() {
            let key = entry["key"].as_str().unwrap();
            let value = hex::decode(entry["value"].as_str().unwrap()).unwrap();
            lines.push(format!("{name} {key} {}", describe_value(name, &value)));
        }
    }
    lines.sort();
    lines.join("\n") + "\n"
}

fn event(stream_id: &str, stream_kind: u8, event_type: &str, plaintext: Vec<u8>) -> EventToWrite {
    EventToWrite {
        stream_id: stream_id.into(),
        event_type: event_type.into(),
        stream_kind,
        record_kind: RecordKind::Event,
        plaintext,
    }
}

