async fn reopen(path: &Path) -> WabiDbEngine {
    let deadline = tokio::time::Instant::now() + std::time::Duration::from_secs(5);
    loop {
        match WabiDbEngine::open(config(path)).await {
            Ok(engine) => return engine,
            Err(crate::error::WabiError::AlreadyRunning)
                if tokio::time::Instant::now() < deadline =>
            {
                tokio::time::sleep(std::time::Duration::from_millis(10)).await;
            }
            Err(error) => panic!("pre-versioning fixture did not open: {error}"),
        }
    }
}

fn copy_dir(from: &Path, to: &Path) {
    std::fs::create_dir_all(to).unwrap();
    for entry in std::fs::read_dir(from).unwrap() {
        let entry = entry.unwrap();
        let target = to.join(entry.file_name());
        if entry.file_type().unwrap().is_dir() {
            copy_dir(&entry.path(), &target);
        } else {
            std::fs::copy(entry.path(), &target).unwrap();
        }
    }
}

/// Copy the committed data directory (without `expected.txt`) to a scratch
/// directory the engine may write to.
fn scratch_copy() -> tempfile::TempDir {
    let scratch = tempfile::tempdir().unwrap();
    copy_dir(&fixture_dir().join("data"), &scratch.path().join("data"));
    scratch
}

fn expected() -> String {
    std::fs::read_to_string(fixture_dir().join("expected.txt")).unwrap()
}

/// Generates the fixture. Run once, before any record encoder changed:
/// `WABIDB_WRITE_PRE_VERSIONING_FIXTURE=1 cargo test -p wabidb --lib -- --ignored write_pre_versioning_fixture`
#[tokio::test]
#[ignore = "writes tests/fixtures; see the module docs before running"]
async fn write_pre_versioning_fixture() {
    if std::env::var_os("WABIDB_WRITE_PRE_VERSIONING_FIXTURE").is_none() {
        return;
    }
    let root = fixture_dir();
    let data = root.join("data");
    assert!(!data.exists(), "refusing to overwrite {}", data.display());
    std::fs::create_dir_all(&data).unwrap();
    let engine = WabiDbEngine::open(config(&data)).await.unwrap();
    for event in fixture_events() {
        engine.get_or_create_stream_key(&event.stream_id).await.unwrap();
        let event_type = event.event_type.clone();
        let (response_tx, _response_rx) = tokio::sync::oneshot::channel();
        engine
            .run_command(CommandCommit {
                room_owner_precondition: None,
                caller_user_id: 7,
                caller_device_id: "fixture".into(),
                command_name: format!("fixture_{event_type}"),
                idempotency_key: None,
                events: vec![event],
                essential: true,
                response_tx,
            })
            .await
            .unwrap_or_else(|e| panic!("{event_type} rejected: {e}"));
    }
    let described = describe_state(&engine.projection_state());
    assert!(!described.contains("DECODE ERROR"), "{described}");
    drop(engine);
    drop(super::wait_for_stopped_engine(&data).await);
    std::fs::write(root.join("expected.txt"), described).unwrap();
}

/// Snapshot present: the projection rows on disk are the old raw postcard
/// bytes, and every one must still decode to what it decoded to before.
#[tokio::test]
async fn pre_versioning_snapshot_still_decodes() {
    let scratch = scratch_copy();
    let data = scratch.path().join("data");
    assert!(ProjectionState::snapshot_path(&data).exists());
    let engine = reopen(&data).await;
    assert_eq!(describe_state(&engine.projection_state()), expected());
}

/// Snapshot removed: the engine replays every old durable event from the log
/// through today's decoders and must rebuild the same projection state.
#[tokio::test]
async fn pre_versioning_log_replays_to_the_same_state() {
    let scratch = scratch_copy();
    let data = scratch.path().join("data");
    std::fs::remove_file(ProjectionState::snapshot_path(&data)).unwrap();
    let engine = reopen(&data).await;
    let state = engine.projection_state();
    assert_eq!(state.applied_commit_seq(), fixture_events().len() as u64);
    assert_eq!(describe_state(&state), expected());
}

/// An upgraded server: old events, then new versioned ones in the same log.
/// A full replay must read both, and the old entries must be unchanged.
#[tokio::test]
async fn pre_versioning_log_with_new_writes_replays() {
    let scratch = scratch_copy();
    let data = scratch.path().join("data");
    let engine = reopen(&data).await;
    let mut member = sample::channel_member();
    member.user_id = 4_200_000_002;
    member.nick = None;
    let new_event = event(
        "channel_members:ch_general",
        1,
        "channel_member_added",
        channel_members::encode_record(&member),
    );
    assert!(crate::format::versioned::is_versioned(&new_event.plaintext));
    engine.get_or_create_stream_key(&new_event.stream_id).await.unwrap();
    let (response_tx, _response_rx) = tokio::sync::oneshot::channel();
    engine
        .run_command(CommandCommit {
            room_owner_precondition: None,
            caller_user_id: 7,
            caller_device_id: "fixture".into(),
            command_name: "fixture_new_member".into(),
            idempotency_key: None,
            events: vec![new_event],
            essential: true,
            response_tx,
        })
        .await
        .unwrap();
    drop(engine);
    drop(super::wait_for_stopped_engine(&data).await);
    std::fs::remove_file(ProjectionState::snapshot_path(&data)).unwrap();

    let engine = reopen(&data).await;
    let state = engine.projection_state();
    assert_eq!(state.applied_commit_seq(), fixture_events().len() as u64 + 1);
    let mut members = channel_members::ChannelMembersProjection::list_members(&state, "ch_general")
        .unwrap();
    members.sort_by_key(|m| m.user_id);
    assert_eq!(members, vec![sample::channel_member(), member]);
    let described = describe_state(&state);
    let lines: Vec<&str> = described.lines().collect();
    for old in expected().lines().filter(|line| !line.starts_with("channel_membership_versions ")) {
        assert!(lines.contains(&old), "old entry changed or missing: {old}");
    }
    assert!(!described.contains("DECODE ERROR"), "{described}");
}

/// Offline inspection replays the whole log and compares the result with the
/// saved projection. Replay re-encodes some rows, so a row the old build saved
/// as raw postcard comes out of this build's replay with a version-1 header.
/// That is the same content, and inspection must say the two match.
async fn inspect(data: &Path) -> crate::error::Result<bool> {
    use crate::engine::offline_inspect::{inspect_frozen, InspectionLimits};
    let indexed =
        crate::commit_index::batcher::read_all_entries(&data.join("global/commit-index")).unwrap();
    let seq = indexed.iter().map(|entry| entry.commit_seq).max().unwrap();
    let prefix = crate::replication::commit_prefix_fingerprint(&indexed, seq);
    inspect_frozen(data, &BOOTSTRAP, seq, &prefix, InspectionLimits::default())
        .await
        .map(|inspected| inspected.receipt.persisted_projection_matches)
}

#[tokio::test]
async fn pre_versioning_directory_passes_offline_inspection() {
    let scratch = scratch_copy();
    let matches = inspect(&scratch.path().join("data")).await;
    assert!(matches!(matches, Ok(true)), "{:?}", matches.map_err(|e| e.to_string()));
}

/// The same after an upgrade: this build opened the old directory, wrote a
/// versioned record, and saved a snapshot that mixes old and new rows.
#[tokio::test]
async fn upgraded_directory_passes_offline_inspection() {
    let scratch = scratch_copy();
    let data = scratch.path().join("data");
    let engine = reopen(&data).await;
    let mut member = sample::channel_member();
    member.user_id = 4_200_000_002;
    let new_event = event(
        "channel_members:ch_general",
        1,
        "channel_member_added",
        channel_members::encode_record(&member),
    );
    engine.get_or_create_stream_key(&new_event.stream_id).await.unwrap();
    let (response_tx, _response_rx) = tokio::sync::oneshot::channel();
    engine
        .run_command(CommandCommit {
            room_owner_precondition: None,
            caller_user_id: 7,
            caller_device_id: "fixture".into(),
            command_name: "fixture_new_member".into(),
            idempotency_key: None,
            events: vec![new_event],
            essential: true,
            response_tx,
        })
        .await
        .unwrap();
    drop(engine);
    drop(super::wait_for_stopped_engine(&data).await);
    assert!(ProjectionState::snapshot_path(&data).exists());

    let matches = inspect(&data).await;
    assert!(matches!(matches, Ok(true)), "{:?}", matches.map_err(|e| e.to_string()));
}
